let leagueCentreRound=null,leagueCentreClub='all',leagueCentreReturn=null;
const leagueResultNames={win:'승',draw:'무',loss:'패'},leagueMatchNames={confirmed:'확정',pending:'미확정',next:'이번 경기',scheduled:'예정',live:'진행 중'};
function leagueFormMarkup(form){return form.length?'<span class="league-form">'+form.map(g=>'<span class="'+g.outcome+'" title="'+g.round+'R '+escapeText(g.opponent.short)+' '+g.goals.join(':')+'">'+leagueResultNames[g.outcome]+'</span>').join('')+'</span>':'<span class="league-no-form">기록 없음</span>';}
function leagueWorkspaceFooter(m,prefix){
 const active=m.matches.find(g=>g.active),record=m.matches.find(g=>g.recordId),label=m.selectedRound+'R · '+m.matches.length+'경기';
 const middle=active?'<button type="button" id="'+(prefix==='league-centre'?'league-current-match':prefix+'-current-match')+'" class="secondary">'+label+' · 경기로</button>':record?'<button type="button" class="secondary" data-league-record="'+escapeText(record.recordId)+'">'+label+' · 우리 기록</button>':'<strong>'+label+'</strong>';
 return '<div class="league-workspace-footer"><button type="button" id="'+(prefix==='league-centre'?'league-round-prev':prefix+'-round-prev')+'" class="secondary" '+(m.selectedRound===1?'disabled':'')+'>이전 라운드</button>'+middle+'<button type="button" id="'+(prefix==='league-centre'?'league-round-next':prefix+'-round-next')+'" class="secondary" '+(m.selectedRound===m.rounds?'disabled':'')+'>다음 라운드</button></div>';
}
function leagueWorkspaceMarkup(m,prefix='league-centre',footer=true){
 const esc=escapeText,me=m.table.find(c=>c.own),focus=m.selected||me,parts=Array.from({length:3},(_,i)=>m.table.slice(i*Math.ceil(m.table.length/3),(i+1)*Math.ceil(m.table.length/3)));
 const compact=typeof innerWidth==='number'&&innerWidth<1024,columns=compact?[['경기','played'],['차','gd'],['점','points']]:[['경기','played'],['승','won'],['무','drawn'],['패','lost'],['득','gf'],['실','ga'],['차','gd'],['점','points']];
 const table=rows=>'<table class="league-workspace-table" data-compact="'+compact+'"><colgroup><col class="rank"><col class="club">'+columns.map(()=>'<col>').join('')+'</colgroup><thead><tr><th>위</th><th>구단</th>'+columns.map(([label])=>'<th>'+label+'</th>').join('')+'</tr></thead><tbody>'+rows.map(c=>'<tr class="'+(c.own?'league-own ':'')+(m.clubId===c.id?'league-selected ':'')+(c.zone||'')+'" data-league-row="'+esc(c.id)+'"><td>'+(m.throughRound?c.rank:'—')+'</td><th scope="row"><button type="button" data-league-club="'+esc(c.id)+'" aria-pressed="'+(m.clubId===c.id)+'" aria-label="'+esc(c.short)+' 경기 필터">'+(typeof clubMark==='function'?clubMark(S.club(c.id)):'')+'<span>'+esc(c.short)+'</span></button></th>'+columns.map(([,key])=>'<td>'+c[key]+'</td>').join('')+'</tr>').join('')+'</tbody></table>';
 const games=m.matches.map(g=>'<li class="'+(g.ourGame?'our-game ':'')+g.status+'" title="'+esc(g.home.name+' 대 '+g.away.name+' · '+leagueMatchNames[g.status])+'"><div class="league-fixture-score"><span>'+esc(g.home.short)+'</span><b>'+ (g.score?g.score.join(':'):'—')+'</b><span>'+esc(g.away.short)+'</span></div><small class="league-fixture-status">'+leagueMatchNames[g.status]+(g.status==='live'?' '+g.minute+'분':'')+(g.ourGame?' · 우리 경기':'')+'</small>'+'</li>').join('');
 const recent=m.selected?'<div class="league-club-form"><b>선택 구단 최근 리그 경기</b>'+leagueFormMarkup(m.selected.form)+'<span>'+m.selected.form.map(g=>g.round+'R '+esc(g.opponent.short)+' '+g.goals.join(':')).join(' · ')+'</span></div>':'';
 return '<section class="league-workspace"><div class="league-workspace-filters"><label>라운드<select id="'+prefix+'-round">'+Array.from({length:m.rounds},(_,i)=>'<option value="'+(i+1)+'"'+(i+1===m.selectedRound?' selected':'')+'>'+(i+1)+'R · '+m.roundStates[i]+'</option>').join('')+'</select></label><label>구단 필터<select id="'+prefix+'-club"><option value="all">전체 구단</option>'+m.clubs.map(c=>'<option value="'+esc(c.id)+'"'+(m.clubId===c.id?' selected':'')+'>'+esc(c.short)+'</option>').join('')+'</select></label><div class="league-workspace-race"><b>'+esc(focus.short)+' · '+(m.throughRound?focus.rank+'위':'개막 전')+' · '+focus.points+'점</b><small>'+focus.won+'승 '+focus.drawn+'무 '+focus.lost+'패 · '+focus.gf+'득 / '+focus.ga+'실'+'</small></div></div><div class="league-workspace-content"><section class="league-workspace-standings" aria-label="리그 전체 순위"><h3>'+m.throughRound+'R '+(compact?'간단 순위':'확정 순위')+' · '+m.table.length+'구단 <small>득·실: 득점·실점 / 차: 득실차 / 점: 승점</small></h3><div class="league-workspace-tables">'+parts.filter(p=>p.length).map(table).join('')+'</div></section><section class="league-workspace-fixtures"><h3>'+m.selectedRound+'R · 전 경기 <small>확정 결과만 공개</small></h3><ul class="league-centre-games">'+games+'</ul>'+recent+'</section></div>'+(footer?leagueWorkspaceFooter(m,prefix):'')+'</section>';
}
function bindLeagueWorkspace(host,m,prefix,redraw,onMatch){
 const focus=id=>{redraw();$(id)?.focus({preventScroll:true});};
 $(prefix+'-round').onchange=e=>{leagueCentreRound=Number(e.target.value);focus(prefix+'-round');};
 $(prefix+'-club').onchange=e=>{leagueCentreClub=e.target.value;focus(prefix+'-club');};
 $(prefix==='league-centre'?'league-round-prev':prefix+'-round-prev').onclick=()=>{if(m.selectedRound>1){leagueCentreRound=m.selectedRound-1;focus(prefix+'-round');}};
 $(prefix==='league-centre'?'league-round-next':prefix+'-round-next').onclick=()=>{if(m.selectedRound<m.rounds){leagueCentreRound=m.selectedRound+1;focus(prefix+'-round');}};
 host.querySelectorAll('[data-league-club]').forEach(b=>b.onclick=()=>{leagueCentreClub=b.dataset.leagueClub;focus(prefix+'-club');});
 host.querySelectorAll('[data-league-record]').forEach(b=>b.onclick=()=>openMatchArchive(b.dataset.leagueRecord));
 const current=$(prefix==='league-centre'?'league-current-match':prefix+'-current-match');if(current)current.onclick=onMatch;
}
function renderLeagueCentre(){
 const dialog=$('league-centre-dialog');if(!dialog?.open)return;const m=LeagueCentre.read(season,{round:leagueCentreRound,clubId:leagueCentreClub});leagueCentreRound=m.selectedRound;leagueCentreClub=m.clubId;
 dialog.innerHTML='<header class="league-centre-head"><div><span class="eyebrow">리그 현황 / '+m.year+' 시즌</span><h2 id="league-centre-title">'+escapeText(m.league)+' · 순위와 전 경기</h2></div><button type="button" class="secondary" id="close-league-centre" aria-label="리그 센터 닫기">닫기</button></header>'+leagueWorkspaceMarkup(m);
 const close=()=>{dialog.close();leagueCentreReturn?.focus?.({preventScroll:true});};$('close-league-centre').onclick=close;dialog.oncancel=e=>{e.preventDefault();close();};
 bindLeagueWorkspace(dialog,m,'league-centre',renderLeagueCentre,()=>{dialog.close();setView('match');$('primary')?.focus({preventScroll:true});});
}
function openLeagueCentre(){const dialog=$('league-centre-dialog');if(!dialog)return;pauseForPlanning();leagueCentreRound=null;leagueCentreClub='all';leagueCentreReturn=document.activeElement;if(!dialog.open)dialog.showModal();renderLeagueCentre();dialog.scrollTop=0;$('close-league-centre').focus({preventScroll:true});}
document.addEventListener('click',event=>{if(event.target.closest('[data-open-league]'))openLeagueCentre();});
